let preguntaId = null, compatible = null, detalle = '', mensajeCliente = '', confianza = 'baja';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  preguntaId = parsed.pregunta_id ?? null;
  compatible = typeof parsed.compatible === 'boolean' ? parsed.compatible : null;
  detalle = (parsed.detalle || '').toString();
  mensajeCliente = (parsed.mensaje_cliente || '').toString();
  confianza = parsed.confianza === 'alta' ? 'alta' : 'baja';
} catch (e) {}

const pendientes = $('Buscar Preguntas Pendientes').item.json.pendientes || [];
let match = pendientes.find((p) => p.id === preguntaId) || null;
if (!match && pendientes.length === 1) match = pendientes[0];
if (!match || compatible === null || !mensajeCliente) confianza = 'baja';

const escapar = (s) => (s || '').toString().replace(/'/g, "''");

return [{
  json: {
    confianza,
    pregunta_id: match ? match.id : null,
    kit_id: match ? match.kit_id : null,
    kit_sql: match ? escapar(match.kit) : '',
    modelo_moto_sql: match ? escapar(match.modelo_moto) : '',
    compatible,
    detalle_sql: escapar(detalle),
    mensaje_cliente: mensajeCliente,
